**Route handler** (`app/api/chat/route.ts`):

```ts
import { openai } from '@ai-sdk/openai';
import { streamText, convertToModelMessages, UIMessage } from 'ai';

export const maxDuration = 30;

export async function POST(req: Request) {
  const { messages }: { messages: UIMessage[] } = await req.json();

  const result = streamText({
    model: openai('gpt-4o'),
    messages: await convertToModelMessages(messages),
  });

  return result.toUIMessageStreamResponse();
}
```

**Client** (`app/page.tsx`):

```tsx
'use client';

import { useChat } from '@ai-sdk/react';
import { useState } from 'react';

export default function Chat() {
  const [input, setInput] = useState('');
  const { messages, sendMessage, status } = useChat(); // defaults to POST /api/chat

  return (
    <div>
      {messages.map(m => (
        <div key={m.id}>
          <strong>{m.role}:</strong>{' '}
          {m.parts.map((part, i) =>
            part.type === 'text' ? <span key={i}>{part.text}</span> : null,
          )}
        </div>
      ))}

      <form
        onSubmit={e => {
          e.preventDefault();
          sendMessage({ text: input });
          setInput('');
        }}
      >
        <input value={input} onChange={e => setInput(e.target.value)} />
        <button disabled={status !== 'ready'}>Send</button>
      </form>
    </div>
  );
}
```

Key points:
- Use `toUIMessageStreamResponse()`, which is the format `useChat` expects. Don't use the older `toDataStreamResponse()`.
- `useChat` now comes from `@ai-sdk/react`, and it no longer manages input state, so you handle `input` yourself.
- To use a different endpoint, pass `transport: new DefaultChatTransport({ api: '/api/other' })` to `useChat`, importing `DefaultChatTransport` from `ai`.

In the current docs (AI SDK 7.x), you wrap `result.stream` with `toUIMessageStream` and return it with `createUIMessageStreamResponse`. `useChat` can read that stream.

**Server: `app/api/chat/route.ts`**

```ts
import {
  streamText,
  convertToModelMessages,
  createUIMessageStreamResponse,
  toUIMessageStream,
  type UIMessage,
} from 'ai';

export const maxDuration = 30;

export async function POST(req: Request) {
  const { messages }: { messages: UIMessage[] } = await req.json();

  const result = streamText({
    model: 'anthropic/claude-sonnet-5.5', // AI Gateway model string, needs AI_GATEWAY_API_KEY
    instructions: 'You are a helpful assistant.',
    messages: await convertToModelMessages(messages), // async in current docs
  });

  return createUIMessageStreamResponse({
    stream: toUIMessageStream({ stream: result.stream }),
  });
}
```

**Client: `app/page.tsx`**

```tsx
'use client';

import { useChat } from '@ai-sdk/react';
import { DefaultChatTransport } from 'ai';
import { useState } from 'react';

export default function Page() {
  const [input, setInput] = useState('');
  const { messages, sendMessage, status } = useChat({
    transport: new DefaultChatTransport({ api: '/api/chat' }), // '/api/chat' is the default
  });

  return (
    <>
      {messages.map(m => (
        <div key={m.id}>
          {m.role}:{' '}
          {m.parts.map((p, i) => (p.type === 'text' ? <span key={i}>{p.text}</span> : null))}
        </div>
      ))}
      <form
        onSubmit={e => {
          e.preventDefault();
          if (input.trim()) {
            sendMessage({ text: input });
            setInput('');
          }
        }}
      >
        <input value={input} onChange={e => setInput(e.target.value)} disabled={status !== 'ready'} />
      </form>
    </>
  );
}
```

**Version differences**

- **v5/v6 (older):** the docs for these versions return `result.toUIMessageStreamResponse()` directly. They use `system:` instead of `instructions:`. In v5, `convertToModelMessages(messages)` is synchronous. If your installed `ai` version is older than 7, use this form:
  ```ts
  return result.toUIMessageStreamResponse();
  ```
- **Don't use these old patterns:**
  - `toDataStreamResponse()` is the old method.
  - `handleSubmit`/`handleInputChange` and `input` from `useChat` no longer exist.
  - `message.content` has been replaced by `message.parts`.
- **Text-only streams:** if you only need plain text, use `createTextStreamResponse` with `toTextStream` on the server. On the client, use `TextStreamChatTransport` instead of `DefaultChatTransport`. That path doesn't carry tool calls.

Check your installed `ai` version with `npm ls ai` to pick the right form.

Convert the incoming UI messages, call `streamText`, and wrap the result with `createUIMessageStreamResponse`. This follows the current docs I found.

**`app/api/chat/route.ts`**
```ts
import {
  convertToModelMessages,
  createUIMessageStreamResponse,
  streamText,
  toUIMessageStream,
  type UIMessage,
} from 'ai';

export async function POST(req: Request) {
  const { messages }: { messages: UIMessage[] } = await req.json();

  const result = streamText({
    model: 'anthropic/claude-sonnet-5.5', // or a provider model, e.g. openai('...')
    messages: await convertToModelMessages(messages),
  });

  return createUIMessageStreamResponse({
    stream: toUIMessageStream({ stream: result.stream }),
  });
}
```

**Client (`app/page.tsx`)**
```tsx
'use client';

import { useChat } from '@ai-sdk/react';
import { useState } from 'react';

export default function Chat() {
  const [input, setInput] = useState('');
  const { messages, sendMessage } = useChat(); // defaults to POST /api/chat

  return (
    <div>
      {messages.map(m => (
        <div key={m.id}>
          {m.role === 'user' ? 'User: ' : 'AI: '}
          {m.parts.map((part, i) =>
            part.type === 'text' ? <span key={i}>{part.text}</span> : null,
          )}
        </div>
