If you're on v8 or earlier, the setup is different. You pass `getSortedRowModel: getSortedRowModel()` directly to `useReactTable` and don't use `tableFeatures`.

TanStack Table has two APIs right now. The v8 API is `useReactTable` with `getSortedRowModel`. The newer v9 docs use `useTable` with `rowSortingFeature`. Check which major version you have installed with `npm ls @tanstack/react-table`.

## v8 (`useReactTable`)

```tsx
import {
  useReactTable,
  getCoreRowModel,
  getSortedRowModel,
  flexRender,
  type ColumnDef,
  type SortingState,
} from '@tanstack/react-table'
import { useState } from 'react'

type Person = { name: string; age: number }

const columns: ColumnDef<Person>[] = [
  { accessorKey: 'name', header: 'Name' },
  { accessorKey: 'age', header: 'Age' },
]

function MyTable({ data }: { data: Person[] }) {
  const [sorting, setSorting] = useState<SortingState>([])

  const table = useReactTable({
    data,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getSortedRowModel: getSortedRowModel(), // enables client-side sorting
  })

  return (
    <table>
      <thead>
        {table.getHeaderGroups().map(hg => (
          <tr key={hg.id}>
            {hg.headers.map(header => (
              <th
                key={header.id}
                onClick={header.column.getToggleSortingHandler()}
                style={{ cursor: header.column.getCanSort() ? 'pointer' : 'default' }}
              >
                {flexRender(header.column.columnDef.header, header.getContext())}
                {{ asc: ' ↑', desc: ' ↓' }[header.column.getIsSorted() as string] ?? null}
              </th>
            ))}
          </tr>
        ))}
      </thead>
      <tbody>
        {table.getRowModel().rows.map(row => (
          <tr key={row.id}>
            {row.getVisibleCells().map(cell => (
              <td key={cell.id}>
                {flexRender(cell.column.columnDef.cell, cell.getContext())}
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  )
}
```

- Clicking a header cycles through ascending, descending and unsorted. Shift-click adds a column to a multi-sort.
- To turn sorting off for one column, set `enableSorting: false` on its column def.
- If you don't need to own the state, use `initialState: { sorting: [{ id: 'name', desc: true }] }` instead of `state` and `onSortingChange`.

