});

for await (const part of result.fullStream) {
  switch (part.type) {
    case 'text-delta':
      process.stdout.write(part.text);
      break;
    case 'tool-call':
      console.log('\nTool call:', part.toolName, part.input);
      break;
    case 'tool-result':
      console.log('Tool result:', part.toolName, part.output);
      break;
    case 'tool-error':
      console.error('Tool error:', part.toolName, part.error);
      break;
    case 'error':
      console.error('Stream error:', part.error);
      break;
    case 'finish':
      console.log('\nFinish:', part.finishReason, part.usage);
      break;
  }
