```ts
import express from "express";
import { McpServer } from "@modelcontextprotocol/sdk/server/mcp.js";
import { StreamableHTTPServerTransport } from "@modelcontextprotocol/sdk/server/streamableHttp.js";
import { z } from "zod";

function createServer() {
  const server = new McpServer({ name: "my-server", version: "1.0.0" });
  server.registerTool(
    "echo",
    { description: "Echo text", inputSchema: { text: z.string() } },
    async ({ text }) => ({ content: [{ type: "text", text }] })
  );
  return server;
}

const app = express();
app.use(express.json());

// Stateless: new server + transport per request
app.post("/mcp", async (req, res) => {
  const server = createServer();
  const transport = new StreamableHTTPServerTransport({
    sessionIdGenerator: undefined, // stateless
  });
  res.on("close", () => {
    transport.close();
    server.close();
  });
  await server.connect(transport);
  await transport.handleRequest(req, res, req.body);
});

app.listen(3000, () => console.log("MCP server on http://localhost:3000/mcp"));
```

Remote clients then connect to `http://your-host:3000/mcp`.

Notes:
- **Stateful sessions:** pass `sessionIdGenerator: () => randomUUID()`, keep a map of transports by the `mcp-session-id` header, and also handle `GET` and `DELETE` on `/mcp`.
- **Production:** put it behind HTTPS and add authentication. If it's reachable from browsers, configure CORS (expose the `Mcp-Session-Id` header) and validate the `Origin` header.
- **Legacy:** the old standalone SSE transport is deprecated in favor of Streamable HTTP.

