  input: "My name is Sam.",
  conversation: conversation.id,
});

// Later turns: send only the new message
const r2 = await client.responses.create({
  model: "gpt-4.1",
  input: "What's my name?",
  conversation: conversation.id,
});

console.log(r2.output_text); // "Your name is Sam."
```

**Lighter alternative: chain responses with `previous_response_id`**

```ts
const a = await client.responses.create({
  model: "gpt-4.1",
  input: "My name is Sam.",
});

const b = await client.responses.create({
  model: "gpt-4.1",
  input: "What's my name?",
  previous_response_id: a.id,
});
```

Notes:
- Use either `conversation` or `previous_response_id` in a single request, not both.
- Stored history still counts as input tokens on each call. You just don't have to resend it.
- Response objects are stored for 30 days by default, while items in a conversation are persisted without that TTL.
- Set `store: false` if you don't want OpenAI to retain the response.

Use the Responses API. There are two ways to keep the history on OpenAI's side.

**Option 1: Conversations API.** This is a durable conversation object. Each response you create with it is appended to it automatically.

```ts
import OpenAI from "openai";

const client = new OpenAI();

// Create the conversation once and keep its ID.
const conversation = await client.conversations.create({
  metadata: { user_id: "user_123" },
});

// Turn 1
const r1 = await client.responses.create({
  model: "gpt-4.1", // use whichever model you prefer
  input: "What is the capital of France?",
  conversation: conversation.id,
});
console.log(r1.output_text);

// Turn 2: send only the new message. Earlier items are prepended server-side.
const r2 = await client.responses.create({
  model: "gpt-4.1",
  input: "And its population?",
  conversation: conversation.id,
});
console.log(r2.output_text);
```

**Option 2: `previous_response_id`.** This chains responses together without creating a conversation object. The earlier response must have been stored (`store: true`, which is the default).

```ts
const res1 = await client.responses.create({
  model: "gpt-4.1",
  input: "What is the capital of France?",
  store: true,
});

const res2 = await client.responses.create({
  model: "gpt-4.1",
  input: "And its population?",
  previous_response_id: res1.id,
  store: true,
});
```

**Things to know**
- `conversation` and `previous_response_id` can't be used in the same request.
- Prior items still count as input tokens on each turn. You only avoid resending them from your side.
- Use `conversation` when you want one long-lived thread that you can look up later. Use `previous_response_id` for simple chaining or for forking from an earlier response.
- If you manage history yourself instead, keep every item in `response.output` in order. Filtering to messages can drop reasoning or tool-call items and make the next request fail. The SDK's `toResponseInputItems()` helper normalizes them for you.

