      transport: "stdio",
      command: "node",
      args: ["/absolute/path/to/math_server.js"],
    },
  },
});

try {
  const tools = await adapter.listTools(); // flat list of LangChain tools
  const agent = createAgent({ model: "anthropic:claude-sonnet-5", tools });

