Use the `firebase/ai` module. Gemini's image-capable model is the simplest route:

```js
import { initializeApp } from "firebase/app";
import {
  getAI,
  getGenerativeModel,
  GoogleAIBackend,
  ResponseModality,
} from "firebase/ai";

const app = initializeApp(firebaseConfig);
const ai = getAI(app, { backend: new GoogleAIBackend() });

const model = getGenerativeModel(ai, {
  model: "gemini-2.5-flash-image",
  generationConfig: {
    responseModalities: [ResponseModality.TEXT, ResponseModality.IMAGE],
  },
});

async function generateImage(prompt) {
  const result = await model.generateContent(prompt);
  const parts = result.response.inlineDataParts();

  if (parts?.length) {
    const { mimeType, data } = parts[0].inlineData;
    document.querySelector("#output").src = `data:${mimeType};base64,${data}`;
  }
}

generateImage("A watercolor painting of a fox in a snowy forest");
```

**Alternative: Imagen models**

```js
import { getAI, getImagenModel, GoogleAIBackend } from "firebase/ai";

const ai = getAI(app, { backend: new GoogleAIBackend() });
const imagen = getImagenModel(ai, { model: "imagen-4.0-generate-001" });

const { images } = await imagen.generateImages("A watercolor fox in a snowy forest");
if (images.length) {
  const img = images[0];
  document.querySelector("#output").src =
    `data:${img.mimeType};base64,${img.bytesBase64Encoded}`;
}
```

**Notes**
- Enable the Firebase AI Logic API in the Firebase console first. Image generation generally requires the Blaze (pay-as-you-go) plan.
- Model names change over time, so check the Firebase docs for the currently supported ones.
- Consider enabling App Check to protect your endpoint from abuse.

Firebase AI Logic is in the `firebase/ai` module. Here is an example using Gemini's native image generation:

```js
import { initializeApp } from "firebase/app";
import {
  getAI,
  getGenerativeModel,
  GoogleAIBackend,
  ResponseModality,
} from "firebase/ai";

const app = initializeApp(firebaseConfig);
const ai = getAI(app, { backend: new GoogleAIBackend() });

const model = getGenerativeModel(ai, {
  model: "gemini-2.5-flash-image",
  generationConfig: {
    responseModalities: [ResponseModality.TEXT, ResponseModality.IMAGE],
  },
});

async function generateImage(prompt) {
  const result = await model.generateContent(prompt);
  const image = result.response.inlineDataParts()?.[0]?.inlineData;
  if (!image) throw new Error("No image returned");

  const img = document.createElement("img");
  img.src = `data:${image.mimeType};base64,${image.data}`;
  document.body.appendChild(img);
}

generateImage("A watercolor painting of a lighthouse at sunrise");
```

**Alternative: Imagen** (image-only output)

```js
import { getAI, getImagenModel, GoogleAIBackend } from "firebase/ai";

const imagen = getImagenModel(ai, { model: "imagen-4.0-generate-001" });

const { images, filteredReason } = await imagen.generateImages(
  "A watercolor painting of a lighthouse at sunrise"
);
if (!images.length) throw new Error(filteredReason ?? "No image returned");

const src = `data:${images[0].mimeType};base64,${images[0].bytesBase64Encoded}`;
```

**Notes**
- Enable the Firebase AI Logic API in the Firebase console first.
- Image generation models generally require the Blaze (pay-as-you-go) plan.
- Model names change over time, so check the Firebase docs for the currently supported ones.
- Consider enabling App Check to protect your quota.

Use a Gemini image model through `firebase/ai`, and set `responseModalities` to `IMAGE`. The docs have a migration guide away from Imagen (`ImagenModel`), so I used the `GenerativeModel` approach. The search tool had no docs indexed for 12.18.0, so this follows the current docs.

```javascript
import { initializeApp } from "firebase/app";
import {
  getAI,
  getGenerativeModel,
  GoogleAIBackend,
  ResponseModality,
  ImageConfigAspectRatio,
  FinishReason,
} from "firebase/ai";

const firebaseApp = initializeApp({ /* your firebaseConfig */ });

// Gemini Developer API backend
const ai = getAI(firebaseApp, { backend: new GoogleAIBackend() });

const model = getGenerativeModel(ai, {
  model: "gemini-3.1-flash-image",
  generationConfig: {
    responseModalities: [ResponseModality.IMAGE], // add TEXT for interleaved text + images
    imageConfig: {                                // optional
      aspectRatio: ImageConfigAspectRatio.LANDSCAPE_4x3,
    },
  },
});

async function generate(prompt) {
  try {
    const result = await model.generateContent(prompt);
    const response = result.response;

    if (response.candidates?.[0].finishReason === FinishReason.NO_IMAGE) {
      console.warn("No image was generated");
      return;
    }

    const part = response.inlineDataParts()?.[0];
    if (part) {
      const { mimeType, data } = part.inlineData; // data is base64
      const img = document.createElement("img");
      img.src = `data:${mimeType};base64,${data}`;
      document.body.appendChild(img);
    }
  } catch (err) {
    console.error("Prompt or candidate was blocked:", err);
  }
}

generate("Generate an image of the Eiffel Tower with fireworks in the background.");
```

- `generateContent` returns a promise, so you need `await`. One of the docs snippets leaves it out, which looks like a typo.
- The image comes back as base64 in `inlineData`. Use it in a `data:` URL, as above.
- Check that your chosen image model is available for your backend (Gemini Developer API or Vertex AI) in the Firebase console.

