In v9, client-side sorting needs three things: `rowSortingFeature`, a `sortedRowModel` slot, and a registered `sortFns` map. All three go in `tableFeatures()`.

```tsx
import {
  useTable,
  tableFeatures,
  rowSortingFeature,
  createSortedRowModel,
  sortFn_alphanumeric,
  sortFn_text,
  sortFn_datetime,
} from '@tanstack/react-table'
import type { ColumnDef } from '@tanstack/react-table'

type Person = { firstName: string; lastName: string; age: number }

const features = tableFeatures({
  rowSortingFeature,
  sortedRowModel: createSortedRowModel(), // client-side sorting
  sortFns: {
    alphanumeric: sortFn_alphanumeric,
    text: sortFn_text,
    datetime: sortFn_datetime,
  },
})

const columns: Array<ColumnDef<typeof features, Person>> = [
  { accessorKey: 'firstName', header: 'First Name' },
  { accessorKey: 'lastName', header: 'Last Name' },
  { accessorKey: 'age', header: 'Age' },
]

export function PersonTable({ data }: { data: Array<Person> }) { // keep `data` referentially stable
  const table = useTable({
    features,
    columns,
    data,
    // initialState: { sorting: [{ id: 'age', desc: true }] }, // optional default sort
  })

  return (
    <table>
      <thead>
        {table.getHeaderGroups().map((hg) => (
          <tr key={hg.id}>
            {hg.headers.map((header) => (
              <th
                key={header.id}
                onClick={header.column.getToggleSortingHandler()}
                style={{ cursor: header.column.getCanSort() ? 'pointer' : undefined }}
              >
                {header.isPlaceholder ? null : <table.FlexRender header={header} />}
                {{ asc: ' ↑', desc: ' ↓' }[header.column.getIsSorted() as string]}
              </th>
            ))}
          </tr>
        ))}
      </thead>
      <tbody>
        {table.getRowModel().rows.map((row) => (
          <tr key={row.id}>
            {row.getAllCells().map((cell) => (
              <td key={cell.id}>
                <table.FlexRender cell={cell} />
              </td>
            ))}
          </tr>
        ))}
      </tbody>
    </table>
  )
}
```

- **Sort functions:** the default `sortFn: 'auto'` picks `alphanumeric`, `text` or `datetime` based on the column's data. Register the ones your columns use. You can also pass a function straight to a column's `sortFn`.
- **Column options:** per column you can set `enableSorting: false`, `sortDescFirst`, `invertSorting` and `sortUndefined: 'last'`.
- **Server-side sorting:** set `manualSorting: true` and drop `sortedRowModel`.
- **Reading sort state:** use `table.state.sorting` in render. Use `table.atoms.sorting.get()` in event handlers.

